import fs from "fs";
import path from "path";

const root = process.cwd();

function t(partial) {
  return partial;
}

function section(slug, title, description, topics) {
  return { slug, title, description, topics };
}

function topic(
  slug,
  title,
  summary,
  estimatedMinutes,
  difficulty,
  keywords,
  challengeWeight,
  explanation,
  commonMistakes,
  bestPractices,
  interviewQuestions,
  cheatSheet
) {
  return t({
    slug,
    title,
    summary,
    estimatedMinutes,
    difficulty,
    keywords,
    challengeWeight,
    explanation,
    a11yNotes: [],
    commonMistakes,
    bestPractices,
    interviewQuestions,
    cheatSheet,
  });
}

function renderCurriculum(typeName, constName, flattenName, sections) {
  const typePrefix = typeName;
  const lines = [];
  lines.push(`export type ${typePrefix}Difficulty = "beginner" | "intermediate" | "advanced";`);
  lines.push("");
  lines.push(`export type ${typePrefix}TopicDef = {`);
  lines.push(`  slug: string;`);
  lines.push(`  title: string;`);
  lines.push(`  summary: string;`);
  lines.push(`  estimatedMinutes: number;`);
  lines.push(`  difficulty: ${typePrefix}Difficulty;`);
  lines.push(`  keywords: string[];`);
  lines.push(`  challengeWeight: number;`);
  lines.push(`  explanation: string;`);
  lines.push(`  a11yNotes: string[];`);
  lines.push(`  commonMistakes: string[];`);
  lines.push(`  bestPractices: string[];`);
  lines.push(`  interviewQuestions: string[];`);
  lines.push(`  cheatSheet: Array<{ tag: string; desc: string }>;`);
  lines.push(`};`);
  lines.push("");
  lines.push(`export type ${typePrefix}SectionDef = {`);
  lines.push(`  slug: string;`);
  lines.push(`  title: string;`);
  lines.push(`  description: string;`);
  lines.push(`  topics: ${typePrefix}TopicDef[];`);
  lines.push(`};`);
  lines.push("");
  lines.push(`function t(partial: ${typePrefix}TopicDef): ${typePrefix}TopicDef {`);
  lines.push(`  return partial;`);
  lines.push(`}`);
  lines.push("");
  lines.push(`export const ${constName}: ${typePrefix}SectionDef[] = ${JSON.stringify(sections, null, 2)};`);
  lines.push("");
  lines.push(`export function ${flattenName}(): ${typePrefix}TopicDef[] {`);
  lines.push(`  return ${constName}.flatMap((section) => section.topics);`);
  lines.push(`}`);
  lines.push("");
  // JSON.stringify already produced valid JS object literals but without `t()` wrappers.
  // Rewrite topics using t({...}) for style parity - optional. Keep as plain objects which match type.
  return lines.join("\n").replaceAll(
    `"a11yNotes": []`,
    `a11yNotes: []`
  );
}

