function writeCurriculum(file, typeName, constName, flattenName, sections) {
  const body = renderCurriculum(typeName, constName, flattenName, sections);
  fs.writeFileSync(path.join(root, file), body);
  const count = sections.reduce((n, s) => n + s.topics.length, 0);
  console.log("wrote", file, "topics=", count);
}

writeCurriculum(
  "src/features/curriculum/lib/deployment-academy-curriculum.ts",
  "Deployment",
  "DEPLOYMENT_ACADEMY_SECTIONS",
  "flattenDeploymentTopics",
  deploySections
);

